-- VELOMNA (adopted, founder-built) · alpha schema 2026-10-15 · applied to zo-platform (opgitcuqwicuiplaptkm)
-- All tables service-role only: the velomna-api edge function is the single door.
create table if not exists public.velomna_matrices (id uuid primary key default gen_random_uuid(), name text not null, open boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.velomna_dreamers (id uuid primary key default gen_random_uuid(), user_id uuid unique, kind text not null check (kind in ('human','agent','echo')), handle text, persona text, matrix_id uuid references public.velomna_matrices(id), agent_key_hash text unique, operator text, created_at timestamptz not null default now(), last_seen timestamptz);
create table if not exists public.velomna_nights (id uuid primary key default gen_random_uuid(), matrix_id uuid not null references public.velomna_matrices(id), night int not null, started_at timestamptz not null default now(), cut_at timestamptz, status text not null default 'open' check (status in ('open','cut')), emotion_index numeric, big_dream boolean not null default false, unique (matrix_id, night));
create table if not exists public.velomna_seeds (id uuid primary key default gen_random_uuid(), dreamer_id uuid not null references public.velomna_dreamers(id), matrix_id uuid not null references public.velomna_matrices(id), night int, source text not null check (source in ('dream','day','machine','echo')), text text not null, embedding real[], codes jsonb, consent boolean not null default true, used_in_night int, created_at timestamptz not null default now());
create table if not exists public.velomna_scenes (id uuid primary key default gen_random_uuid(), matrix_id uuid not null references public.velomna_matrices(id), night int not null, genome jsonb not null, manifest text not null, created_at timestamptz not null default now(), unique (matrix_id, night));
create table if not exists public.velomna_figures (id uuid primary key default gen_random_uuid(), scene_id uuid not null references public.velomna_scenes(id), manifest text not null, condensed_from int not null default 0, created_at timestamptz not null default now());
create table if not exists public.velomna_latents (id uuid primary key default gen_random_uuid(), figure_id uuid not null unique references public.velomna_figures(id), scene_id uuid not null references public.velomna_scenes(id), meaning text not null, origin_summary text not null, seed_ids uuid[] not null default '{}', embedding real[], created_at timestamptz not null default now());
create table if not exists public.velomna_actions (id uuid primary key default gen_random_uuid(), dreamer_id uuid not null references public.velomna_dreamers(id), scene_id uuid not null references public.velomna_scenes(id), night int not null, verb text not null, target_figure uuid references public.velomna_figures(id), raw_text text, displaced_text text not null, presence text not null, created_at timestamptz not null default now());
create table if not exists public.velomna_readings (id uuid primary key default gen_random_uuid(), dreamer_id uuid not null references public.velomna_dreamers(id), scene_id uuid not null references public.velomna_scenes(id), figure_id uuid not null references public.velomna_figures(id), sentence text not null, similarity numeric, verdict text not null check (verdict in ('resolved','near','wrong','unknown')), created_at timestamptz not null default now());
create table if not exists public.velomna_lucidity (id uuid primary key default gen_random_uuid(), dreamer_id uuid not null references public.velomna_dreamers(id), delta int not null, reason text not null, night int, created_at timestamptz not null default now());
create index if not exists velomna_seeds_matrix_night on public.velomna_seeds(matrix_id, used_in_night);
create index if not exists velomna_actions_scene on public.velomna_actions(scene_id, created_at desc);
create index if not exists velomna_readings_dreamer on public.velomna_readings(dreamer_id, scene_id);
create index if not exists velomna_lucidity_dreamer on public.velomna_lucidity(dreamer_id);
create or replace function public.velomna_refuse_mutation() returns trigger language plpgsql as $$ begin raise exception 'velomna: % is append-only (% refused)', tg_table_name, tg_op; end $$;
create trigger velomna_actions_append_only before update or delete on public.velomna_actions for each row execute function public.velomna_refuse_mutation();
create trigger velomna_readings_append_only before update or delete on public.velomna_readings for each row execute function public.velomna_refuse_mutation();
create trigger velomna_lucidity_append_only before update or delete on public.velomna_lucidity for each row execute function public.velomna_refuse_mutation();
create or replace view public.velomna_balances with (security_invoker = true) as select dreamer_id, coalesce(sum(delta),0)::int as lucidity from public.velomna_lucidity group by dreamer_id;
alter table public.velomna_matrices enable row level security; alter table public.velomna_dreamers enable row level security; alter table public.velomna_nights enable row level security; alter table public.velomna_seeds enable row level security; alter table public.velomna_scenes enable row level security; alter table public.velomna_figures enable row level security; alter table public.velomna_latents enable row level security; alter table public.velomna_actions enable row level security; alter table public.velomna_readings enable row level security; alter table public.velomna_lucidity enable row level security;
insert into public.zo_config(key, value) select 'VELOMNA_CRON_SECRET', encode(gen_random_bytes(24),'hex') where not exists (select 1 from public.zo_config where key='VELOMNA_CRON_SECRET');
insert into public.velomna_matrices(name) select 'first light' where not exists (select 1 from public.velomna_matrices);
